mapper.select:
SELECT id, tenant_id, position_code, position_name, organization_id, sort_order, description, status, version, created_at, updated_at FROM iam_position WHERE tenant_id = #{tenantId} AND delete_marker = 0
AND organization_id = #{organizationId}
AND status = #{status}
AND (position_code LIKE CONCAT('%', #{keyword}, '%') OR position_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sort_order ASC, id ASC

mapper.update:
UPDATE iam_team
SET parent_team_id = #{newParentTeamId}, version = version + 1, updated_at = NOW()
WHERE tenant_id = #{tenantId} AND id = #{teamId} AND version = #{expectedVersion}

UPDATE iam_team_member
SET membership_status = 'LEFT', active_slot = NULL, left_at = NOW(),
    version = version + 1, updated_at = NOW()
WHERE tenant_id = #{tenantId} AND team_id = #{teamId} AND user_id = #{userId}
  AND membership_status = 'ACTIVE' AND active_slot = 1 AND version = #{expectedVersion}
